class Solution {
  public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
    int states = 1;
    for (int i = 0; i < n; i++) states *= 3;
    int[][] dig = new int[states][n];
    int[] in = new int[states], ex = new int[states], score = new int[states];
    for (int mask = 0; mask < states; mask++) {
      int x = mask;
      for (int j = 0; j < n; j++) {
        dig[mask][j] = x % 3;
        x /= 3;
        if (dig[mask][j] == 1) in[mask]++;
        if (dig[mask][j] == 2) ex[mask]++;
        score[mask] += dig[mask][j] == 1 ? 120 : dig[mask][j] == 2 ? 40 : 0;
        if (j > 0) score[mask] += pair(dig[mask][j], dig[mask][j - 1]);
      }
    }
    int[][][][] memo = new int[m + 1][introvertsCount + 1][extrovertsCount + 1][states];
    for (int[][][] a : memo) for (int[][] b : a) for (int[] c : b) java.util.Arrays.fill(c, -1);
    return dfs(m, n, states, dig, in, ex, score, memo, 0, 0, 0, 0);
  }

  private int dfs(
      int rows,
      int n,
      int states,
      int[][] dig,
      int[] in,
      int[] ex,
      int[] score,
      int[][][][] memo,
      int row,
      int ci,
      int ce,
      int prev) {
    if (row == rows) return 0;
    if (memo[row][ci][ce][prev] >= 0) return memo[row][ci][ce][prev];
    int best = 0;
    for (int mask = 0; mask < states; mask++)
      if (ci + in[mask] < memo[0].length && ce + ex[mask] < memo[0][0].length) {
        int cross = 0;
        for (int j = 0; j < n; j++) cross += pair(dig[mask][j], dig[prev][j]);
        best =
            Math.max(
                best,
                score[mask]
                    + cross
                    + dfs(
                        rows,
                        n,
                        states,
                        dig,
                        in,
                        ex,
                        score,
                        memo,
                        row + 1,
                        ci + in[mask],
                        ce + ex[mask],
                        mask));
      }
    return memo[row][ci][ce][prev] = best;
  }

  private int pair(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return a == 1 && b == 1 ? -60 : a == 2 && b == 2 ? 40 : -10;
  }
}
